def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    try:
        nanoseconds = int(nanoseconds)
    except ValueError:
        raise ValueError("Invalid nanoseconds value: {}".format(nanoseconds))
    if tz is not None:
        try:
            tz = pytz.timezone(tz)
        except pytz.UnknownTimeZoneError:
            raise ValueError("Invalid time zone: {}".format(tz))
    return Time(nanoseconds, tz)

def dehydrate_timedelta(value):
    """ Dehydrator for `timedelta` values.

    :param value:
    :type value: timedelta
    :return:
    """
    try:
        return {"days": value.days, "seconds": value.seconds, "microseconds": value.microseconds}
    except AttributeError:
        raise TypeError("Invalid type for dehydration: {}".format(type(value)))

def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    if not isinstance(value, Time):
        raise TypeError("Expected Time object, got {}".format(type(value)))
    return value.isoformat()

def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    if not isinstance(value, Point):
        raise TypeError("Value must be a Point instance")

    return {
        "x": value.x,
        "y": value.y,
        "z": value.z
    }

def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    try:
        return list(self.data.keys())
    except AttributeError:
        return []

def protocol_handlers(cls, protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    if protocol_version is None:
        return {version: cls._protocol_handlers[version] for version in cls._protocol_handlers}
    else:
        if not isinstance(protocol_version, tuple):
            raise TypeError("Protocol version must be passed in a tuple")
        if protocol_version in cls._protocol_handlers:
            return {protocol_version: cls._protocol_handlers[protocol_version]}
        else:
            return {}

def index(self, key):
    """ Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    try:
        return self.items.index(key)
    except ValueError:
        return -1

def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    if not keys:
        return list(self.values())
    else:
        return [self.values()[key] for key in keys]

def data(self, *keys):
    """ Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    result = {}
    if not keys:
        keys = self.keys()
    for key in keys:
        try:
            result[key] = self[key]
        except KeyError:
            result[key] = None
    return result

def round_half_to_even(n):
    """
    Round a number to the nearest even integer.

    :param n: The number to round.
    :return: The rounded number.
    """
    if n % 2 == 0:
        return n
    else:
        return n + 1

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(message, DeprecationWarning)
            return func(*args, **kwargs)
        return wrapper
    return decorator

def xargs(cmd, varargs, *, color=False, target_concurrency=1, _max_length=_get_platform_max_length(), **kwargs):
    """A simplified implementation of xargs.

    color: Make a pty if on a platform that supports it
    target_concurrency: Target number of partitions to run concurrently
    """
    # Validate input
    if not isinstance(cmd, tuple) or not all(isinstance(c, str) for c in cmd):
        raise TypeError("cmd must be a tuple of strings")
    if not isinstance(varargs, Sequence) or not all(isinstance(v, str) for v in varargs):
        raise TypeError("varargs must be a sequence of strings")
    if not isinstance(color, bool):
        raise TypeError("color must be a boolean")
    if not isinstance(target_concurrency, int) or target_concurrency < 1:
        raise ValueError("target_concurrency must be a positive integer")
    if not isinstance(_max_length, int) or _max_length < 1:
        raise ValueError("_max_length must be a positive integer")

    # Initialize variables
    partitions = []
    partition_size = len(varargs) // target_concurrency
    remainder = len(varargs) % target_concurrency

    # Create partitions
    for i in range(target_concurrency):
        start = i * partition_size
        end = start + partition_size
        if i < remainder:
            end += 1
        partitions.append(varargs[start:end])

    # Run commands in parallel
    results = []
    with concurrent.futures.ThreadPoolExecutor(max_workers=target_concurrency) as executor:
        future_to_partition = {executor.submit(run_command, cmd, partition, color, _max_length, **kwargs): partition for partition in partitions}
        for future in concurrent.futures.as_completed(future_to_partition):
            partition = future_to_partition[future]
            try:
                results.append((partition, future.result()))
            except Exception as e:
                results.append((partition, e))

    # Return results
    return tuple(results)

def _shuffled(seq: Sequence[str]) -> list[str]:
    """Deterministically shuffle"""
    if not isinstance(seq, Sequence):
        raise TypeError("Expected a sequence, got {type(seq).__name__}")
    if not all(isinstance(x, str) for x in seq):
        raise TypeError("Expected a sequence of strings, got {type(seq).__name__}")
    return list(seq)

