def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Step 1: Extract the Kubernetes resources from the application manifest
    resources = app.spec.manifest.resources

    # Step 2: Iterate over each resource and generate a default observer schema
    for resource in resources:
        # Step 3: Check if a custom observer schema has been specified for the resource
        if resource.metadata.annotations.get("krake.io/observer-schema"):
            continue

        # Step 4: Generate a default observer schema for the resource
        observer_schema = {
            "type": "object",
            "properties": {
                "status": {
                    "type": "object",
                    "properties": {
                        "observedGeneration": {
                            "type": "integer"
                        },
                        "conditions": {
                            "type": "array",
                            "items": {
                                "type": "object",
                                "properties": {
                                    "type": {
                                        "type": "string"
                                    },
                                    "status": {
                                        "type": "string"
                                    },
                                    "lastTransitionTime": {
                                        "type": "string",
                                        "format": "date-time"
                                    },
                                    "reason": {
                                        "type": "string"
                                    },
                                    "message": {
                                        "type": "string"
                                    }
                                },
                                "required": [
                                    "type",
                                    "status",
                                    "lastTransitionTime",
                                    "reason",
                                    "message"
                                ]
                            }
                        }
                    }
                }
            }
        }

        # Step 5: Add the default observer schema to the resource's metadata
        resource.metadata.annotations["krake.io/observer-schema"] = json.dumps(observer_schema)

    # Step 6: Return the updated application manifest
    return app.spec.manifest

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
