def render(pieces, style):
    """Render the given version pieces into the requested style."""
    if not isinstance(pieces, list):
        raise TypeError("pieces must be a list")
    if not isinstance(style, str):
        raise TypeError("style must be a string")
    if style not in ["semver", "pep440"]:
        raise ValueError("style must be either 'semver' or 'pep440'")

    if style == "semver":
        return ".".join(str(piece) for piece in pieces)
    elif style == "pep440":
        return ".".join(str(piece) for piece in pieces) + ".dev0"
    else:
        raise ValueError("Invalid style")

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    if "+" in pieces:
        return "."
    else:
        return "+"

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if not isinstance(commands, (list, tuple)):
        commands = [commands]
    if not isinstance(args, (list, tuple)):
        args = [args]
    if cwd is not None and not isinstance(cwd, str):
        raise TypeError("cwd must be a string")
    if not isinstance(verbose, bool):
        raise TypeError("verbose must be a boolean")
    if not isinstance(hide_stderr, bool):
        raise TypeError("hide_stderr must be a boolean")
    if env is not None and not isinstance(env, dict):
        raise TypeError("env must be a dictionary")

    for command in commands:
        if not isinstance(command, str):
            raise TypeError("command must be a string")
        if not command:
            raise ValueError("command cannot be empty")

    for arg in args:
        if not isinstance(arg, str):
            raise TypeError("arg must be a string")
        if not arg:
            raise ValueError("arg cannot be empty")

    if cwd is not None:
        os.chdir(cwd)

    if env is not None:
        for key, value in env.items():
            os.environ[key] = value

    if verbose:
        print("Running command:", " ".join(commands))

    try:
        result = subprocess.run(commands, args, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        if hide_stderr:
            result.stderr = b""
        return result.stdout.decode("utf-8")
    except subprocess.CalledProcessError as e:
        raise RuntimeError("Command failed with exit code {}: {}".format(e.returncode, " ".join(commands))) from e

def register_vcs_handler(vcs, method):
    """Create decorator to mark a method as the handler of a VCS."""
    def wrapper(*args, **kwargs):
        try:
            method(*args, **kwargs)
        except Exception as e:
            print(f"Error handling VCS {vcs}: {e}")
    return wrapper

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    # Validate the root directory
    if not os.path.isdir(self.root_dir):
        raise ValueError("Root directory does not exist")

    # Validate the objects in the root directory
    for obj in os.listdir(self.root_dir):
        num_objects += 1
        obj_path = os.path.join(self.root_dir, obj)
        if not os.path.isfile(obj_path):
            continue
        if validate_objects and not self.validate_object(obj_path):
            continue
        if check_digests and not self.check_digest(obj_path):
            continue
        good_objects += 1

    # Validate the subdirectories
    for subdir in os.listdir(self.root_dir):
        subdir_path = os.path.join(self.root_dir, subdir)
        if not os.path.isdir(subdir_path):
            continue
        for obj in os.listdir(subdir_path):
            num_objects += 1
            obj_path = os.path.join(subdir_path, obj)
            if not os.path.isfile(obj_path):
                continue
            if validate_objects and not self.validate_object(obj_path):
                continue
            if check_digests and not self.check_digest(obj_path):
                continue
            good_objects += 1

    return num_objects, good_objects

