def size_to_bytes(size: str) -> int:
    """
    Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    try:
        size = size.upper()
        if size.endswith("K"):
            return int(size[:-1]) * 1000
        elif size.endswith("M"):
            return int(size[:-1]) * 1000000
        elif size.endswith("G"):
            return int(size[:-1]) * 1000000000
        else:
            return int(size)
    except ValueError:
        raise ValueError("Invalid size format")

def _dictsum(dicts):
    result = {}
    for d in dicts:
        for key, value in d.items():
            if key not in result:
                result[key] = value
            else:
                result[key] += value
    return result

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    # Step 1: Parse the URL and extract the custom string items
    parsed_url = urlparse(url)
    custom_string_items = re.findall(r'\{([^}]+)\}', parsed_url.path)

    # Step 2: Replace the custom string items with values from args
    for item in custom_string_items:
        if item in url_args:
            parsed_url.path = parsed_url.path.replace('{' + item + '}', url_args[item])

    # Step 3: Return the modified URL
    return parsed_url.geturl()

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    try:
        if val.lower() == "none" or val.lower() == "null" or val.lower() == "nil":
            return True
        else:
            return False
    except AttributeError:
        return False

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated string.
    """
    try:
        flags = []
        for action in parser._actions:
            flags.extend(action.option_strings)
        return " ".join(flags)
    except Exception as e:
        raise ValueError("Failed to retrieve argument flags") from e

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not isinstance(number, int):
        raise TypeError("number must be an integer")
    if not isinstance(alphabet, list):
        raise TypeError("alphabet must be a list")
    if not all(isinstance(x, str) for x in alphabet):
        raise TypeError("alphabet must contain only strings")
    if padding is not None and not isinstance(padding, int):
        raise TypeError("padding must be an integer")

    if number == 0:
        return alphabet[0]

    result = ""
    base = len(alphabet)
    while number > 0:
        result = alphabet[number % base] + result
        number //= base

    if padding is not None:
        result = result.rjust(padding, alphabet[0])

    return result

def _replace_register(flow_params, register_number, register_value):
    """Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number

    """
    try:
        for flow in flow_params:
            if register_value in flow:
                flow[register_number] = flow.pop(register_value)
    except KeyError:
        raise ValueError(f"Invalid register number: {register_number}")
    except TypeError:
        raise TypeError("Invalid flow_params type, must be a dictionary")

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    if not isinstance(value, str):
        raise ValueError("value must be a string")
    if not isinstance(arg, str):
        raise ValueError("arg must be a string")
    return value.replace(".", arg)

def unquote(name):
